practice.solution:
def viterbi(obs, states, start_p, trans_p, emit_p):
    n = len(states)
    E = []
    for lst in emit_p:
        d = {}
        for o, p in lst:
            d[o] = p
        E.append(d)
    V = [[0.0] * n for _ in obs]
    B = [[0] * n for _ in obs]
    for s in range(n):
        V[0][s] = start_p[s] * E[s].get(obs[0], 0.0)
    for t in range(1, len(obs)):
        for s in range(n):
            best = -1.0
            arg = 0
            for p in range(n):
                v = V[t - 1][p] * trans_p[p][s]
                if v > best + 1e-15:
                    best = v
                    arg = p
            V[t][s] = best * E[s].get(obs[t], 0.0)
            B[t][s] = arg
    last = 0
    bv = -1.0
    for s in range(n):
        if V[-1][s] > bv + 1e-15:
            bv = V[-1][s]
            last = s
    path = [last]
    for t in range(len(obs) - 1, 0, -1):
        last = B[t][last]
        path.append(last)
    path.reverse()
    return [states[i] for i in path]

