def cky(words, lexicon, rules):
    n = len(words)
    chart = [[set() for _ in range(n + 1)] for _ in range(n + 1)]
    for i in range(n):
        for w, c in lexicon:
            if w == words[i]:
                chart[i][i + 1].add(c)
    for span in range(2, n + 1):
        for i in range(0, n - span + 1):
            j = i + span
            for k in range(i + 1, j):
                for p, l, r in rules:
                    if l in chart[i][k] and r in chart[k][j]:
                        chart[i][j].add(p)
    return 'S' in chart[0][n]

